-- Fakt kartochkalari orqa tomonining ruscha matni — 68-partiya:
-- Kunxo'ja, Lutfixonim Sarimsoqova, Lutfiy.

UPDATE fact_cards SET detail_ru = 'В энциклопедии полное имя поэта дано как Кунходжа, сын Ибрагима, а годы жизни указаны 1799–1880. Сведений о месте его рождения в этом источнике нет, потому оно точно неизвестно. Источник: Национальная энциклопедия Узбекистана, статья «Кунходжа».' WHERE id = 2203;
UPDATE fact_cards SET detail_ru = 'В Национальной энциклопедии Узбекистана Кунходжа коротко и определённо назван «каракалпакским поэтом». Его сочинения считаются частью каракалпакской классической поэзии. Источник: Национальная энциклопедия Узбекистана, статья «Кунходжа».' WHERE id = 2204;
UPDATE fact_cards SET detail_ru = 'По энциклопедии, в этих стихах отражены жизнь каракалпаков, тяготы быта и надежды на приход лучших дней. В одной из статей на Ziyouz.com в качестве эпиграфа приведён краткий отрывок из стихотворения «Белый камыш»: «Белый камыш, эй, белый камыш, не сохни, стоя в воде». Источник: Национальная энциклопедия Узбекистана, статья «Кунходжа»; Ziyouz.com — Уразбай Абдурахманов, статья «Арал: перед белой стеной…».' WHERE id = 2205;
UPDATE fact_cards SET detail_ru = 'Как сказано в энциклопедии, в этих стихах раскрыты общественные противоречия и несправедливость, обличены дела людей бессовестных и немилосердных. Источник: Национальная энциклопедия Узбекистана, статья «Кунходжа».' WHERE id = 2206;
UPDATE fact_cards SET detail_ru = 'Сочинения «Не забуду», «Ты, оказывается, верблюд», «Где день» считаются лучшими образцами каракалпакской классической поэзии. Источник: Национальная энциклопедия Узбекистана, статья «Кунходжа».' WHERE id = 2207;
UPDATE fact_cards SET detail_ru = 'В статье на сайте Национального информационного агентства Узбекистана УзА упоминается, что Бердах читал свои стихи в присутствии Кунходжи и исправлял в них недостатки. Как пишет автор статьи, это показывает, насколько высокой была у Бердаха ответственность за слово. Источник: УзА (uza.uz) — Гайрат Мажид, «Дух предков да будет наставником…», 5 июля 2022 года.' WHERE id = 2208;
UPDATE fact_cards SET detail_ru = 'В энциклопедии годы жизни Кунходжи указаны как 1799–1880. Сведений о месте его смерти и о могиле в этом источнике не даётся, потому они точно неизвестны. Источник: Национальная энциклопедия Узбекистана, статья «Кунходжа».' WHERE id = 2209;
UPDATE fact_cards SET detail_ru = 'По энциклопедии, стихотворный сборник поэта — «Стихи» — был издан на узбекском языке в переводе Захиджана Обидова в 1973 году. А в разделе «Каракалпакская поэзия» библиотеки Ziyouz.com хранятся его книги «Косиклар» («Песни», 1960) и «Эль менен» («С народом», 1975, 1984, 1989), а также сборник «Хрестоматия по словесности. Жиен-жырау, Кунходжа, Бердах». Источник: Национальная энциклопедия Узбекистана, статья «Кунходжа»; библиотека Ziyouz.com, раздел «Каракалпакская поэзия».' WHERE id = 2210;

UPDATE fact_cards SET detail_ru = 'Лутфихоним Сарымсакова родилась в 1896 году в Риштанском районе Ферганской области. Источник: УзА, статья «Со дня рождения Лутфихоним Сарымсаковой исполнилось 130 лет».' WHERE id = 2211;
UPDATE fact_cards SET detail_ru = 'Лутфихоним Сарымсакова пришла в театр в 1924 году в Коканде через женский любительский кружок. В театр её пригласил Хамза Хакимзаде Ниязи. Позже она работала в кокандском, андижанском и маргиланском театрах. Источник: УзА, статья «Со дня рождения Лутфихоним Сарымсаковой исполнилось 130 лет».' WHERE id = 2212;
UPDATE fact_cards SET detail_ru = 'На сцене Узбекского государственного музыкального театра (театра имени Мукими) она создала множество образов: Ойсары в «Гульсаре», Кимё в «Нурхон», старухи Ясуман в «Фархаде и Ширин», матери в «Халиме», Майсары в «Проделках Майсары». Источник: УзА, статья «Со дня рождения Лутфихоним Сарымсаковой исполнилось 130 лет».' WHERE id = 2213;
UPDATE fact_cards SET detail_ru = 'Её известные работы в кино — образ матери в фильме «Клятва», Мехринисо в «Об этом говорит вся махалля» и тётушки Фатимы в «Ты не сирота». Играла она и в фильмах «Дети» и «Сёстры Рахмановы». Источник: УзА, статья «Со дня рождения Лутфихоним Сарымсаковой исполнилось 130 лет».' WHERE id = 2214;
UPDATE fact_cards SET detail_ru = 'Лутфихоним Сарымсакова была известна такими песнями и лапарами, как «Смейся», «Иначе», «Ёр-ёр», «Будем здоровы», «Не дрожи». В 1939–1940 годах она была устроительницей и художественным руководителем женского ансамбля дутаристок при Узбекской государственной филармонии. Источник: УзА, статья «Со дня рождения Лутфихоним Сарымсаковой исполнилось 130 лет».' WHERE id = 2215;
UPDATE fact_cards SET detail_ru = 'Звание народной артистки Узбекистана было присвоено Лутфихоним Сарымсаковой в 1937 году, во время декады в Москве. В том же году газета «Правда» признала её обладательницей большого драматического дарования. Источник: УзА, статья «Со дня рождения Лутфихоним Сарымсаковой исполнилось 130 лет».' WHERE id = 2216;
UPDATE fact_cards SET detail_ru = 'В годы Второй мировой войны Лутфихоним Сарымсакова взяла на воспитание двух русских детей и растила их с глубокой сердечностью. Это дело показало, что она достойна имени «Ая» — «матушка», которым звал её народ. Источник: УзА, статья «Со дня рождения Лутфихоним Сарымсаковой исполнилось 130 лет».' WHERE id = 2217;
UPDATE fact_cards SET detail_ru = 'Год её смерти в источнике точно не указан; УзА описывает её жизнь как «почти вековую», почётную и непростую. После её кончины, в 2001 году, артистка была награждена орденом «За великие заслуги», а о ней созданы документальные фильмы «Ая» и «Тётушка Лутфихон». Источник: УзА, статья «Со дня рождения Лутфихоним Сарымсаковой исполнилось 130 лет».' WHERE id = 2218;

UPDATE fact_cards SET detail_ru = 'Мавляна Лутфи родился в 1366 году. В традиционных источниках местом его рождения и смерти указывается Герат; на основании того, что в сочинении шейха Ахмада Тарази «Фунун уль-балога» он назван «Лутфи Шаши», высказывалось и мнение, что подлинной его родиной был Ташкент. Источник: Ziyouz.com, статья «Мавляна Лутфи (1366–1465)».' WHERE id = 2219;
UPDATE fact_cards SET detail_ru = 'Лутфи был признан в своё время «малик уль-калам» — царём слова. Алишер Навои описал его как царя слова своего времени, поэта, которому нет равных ни в персидском, ни в тюркском; сведения об этом даны в тазкире «Маджолис ун-нафоис». Источник: Ziyouz.com, статья «Мавляна Лутфи (1366–1465)».' WHERE id = 2220;
UPDATE fact_cards SET detail_ru = 'Известности Лутфи достиг стихами, созданными на родном тюркском языке, показал он своё мастерство и в персидском. Навои описал его как поэта, которому нет равных ни в персидском, ни в тюркском. Источник: Ziyouz.com, статья «Мавляна Лутфи (1366–1465)».' WHERE id = 2221;
UPDATE fact_cards SET detail_ru = 'Поэзия Лутфи насчитывает более 2774 бейтов, из них 2086 бейтов — газели; в диване есть и такие жанры, как рубаи, туюг, кыта и фард, а в рукописи включены и мухаммасы, написанные по вдохновению от газелей Лутфи. Тридцать три рукописных списка дивана, переписанных в XVI–XX веках, хранятся в библиотеках Ташкента, Душанбе, Стамбула, Тегерана, Лондона, Парижа и Санкт-Петербурга. Источник: Ziyouz.com, статья «Мавляна Лутфи (1366–1465)».' WHERE id = 2222;
UPDATE fact_cards SET detail_ru = 'Строки «Ты моя любимая, хочешь верь, хочешь не верь, / Кровью исходит печень моя, хочешь верь, хочешь не верь» считаются одним из самых известных образцов поэзии Лутфи; на странице источника эти строки приведены как образец простого, близкого к разговорной речи и искреннего слога. Источник: Ziyouz.com, статья «Мавляна Лутфи (1366–1465)».' WHERE id = 2223;
UPDATE fact_cards SET detail_ru = 'Поэма «Гуль и Навруз» прежде считалась сочинением Лутфи. Последующие же исследования подтвердили, что эта поэма принадлежит перу Хайдара Хорезми. Источник: Ziyouz.com, статья «Мавляна Лутфи (1366–1465)».' WHERE id = 2224;
UPDATE fact_cards SET detail_ru = 'Навои с почтением упоминал Лутфи в сочинениях «Маджолис ун-нафоис» и «Насоим уль-мухаббат» и чтил его как царя слова своего времени. Лутфи создал в тюркской поэзии целую творческую школу: у этой школы напрямую учился юный Алишер Навои, а поэт следующего поколения Захириддин Мухаммад Бабур наслаждался поэзией Лутфи и испытал её влияние. Лутфи слагал стихи и после девяноста лет. Источник: Ziyouz.com, статья «Мавляна Лутфи (1366–1465)».' WHERE id = 2225;
UPDATE fact_cards SET detail_ru = 'Мавляна Лутфи умер в 1465 году в возрасте девяноста девяти лет; в традиционных источниках местом его смерти указывается Герат. Его стихи дошли до стран Ближнего и Среднего Востока и читались с наслаждением и среди османских турецких поэтов. Источник: Ziyouz.com, статья «Мавляна Лутфи (1366–1465)».' WHERE id = 2226;
